            for e in r2["entities"]:
                if e["type"] == "transport-belt" and e["dir"] == d and moved == 0:
                    cx = jx
                    cy = jy
                    moved = 1
    if moved == 0:
        cx = cx + dx[d]
        cy = cy + dy[d]
